uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float width : 0.02 .. 0.5 = 0.12;
uniform float bright : 0.0 .. 1.0 = 1.0;

state fixed ph;

void update() {
  ph = fract(ph + fixed(dt) * fixed(speed) * fixed(0.25));
}

vec3 shade(Led led) {
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  fixed band = clamp(fixed(1.0) - abs(frac(ang - ph)) / fixed(0.08), fixed(0.0), fixed(1.0));
  vec3 red   = vec3(1.0, 0.0, 0.0);
  vec3 blue  = vec3(0.0, 0.0, 1.0);
  vec3 c = mix(blue, red, step(fixed(0.5), band));
  return c * band * float(bright);
}

uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float width : 0.02 .. 0.5 = 0.12;
uniform float bright : 0.0 .. 1.0 = 1.0;

state fixed ph;

void update() {
  ph = fract(ph + fixed(dt) * fixed(speed) * fixed(0.25));
}

vec3 shade(Led led) {
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  fixed d = abs(fract(ang - ph));
  fixed band = clamp(fixed(1.0) - d / fixed(0.08), fixed(0.0), fixed(1.0));
  vec3 c = mix(vec3(0.0, 0.0, 1.0), vec3(1.0, 0.0, 0.0), step(fixed(0.5), band));
  return c * band * float(bright);
}
